import {P} from './palette.js';
import {oval,leaf,line,star,shadow} from './shapes.js';
import {cabbage} from './plants.js';
import {clamp} from './animation.js';
export function drawProjectile(c,s,T,time,cosmetic={}){const sniper=s.sniper||cosmetic.evolution==='sniperPea',target=s.target||s,dx=target.x-s.x,dy=target.y-s.y,angle=Math.atan2(dy,dx),distance=Math.hypot(target.x-(s.startX??s.x),target.y-(s.startY??s.y)),travel=Math.hypot(s.x-(s.startX??s.x),s.y-(s.startY??s.y)),arc=s.splash?Math.sin(clamp(travel/Math.max(.1,distance))*Math.PI)*(s.siege?37:25):0,x=s.x*T,y=s.y*T;shadow(c,x,y+4,s.splash?(s.siege?10:6):3,arc);c.save();c.translate(x,y-arc);c.rotate(s.splash?time*5+travel:angle);if(s.splash){if(s.siege){c.globalAlpha=.3;line(c,[[-22,3],[-7,0]],P.cream,9);c.globalAlpha=1}cabbage(c,0,0,s.siege?14:8,time);if(s.fragment){leaf(c,-7,2,4,-1);leaf(c,5,4,4,1)}c.restore();return}if(s.heroId){drawHeroShot(c,s,time,travel);c.restore();return}const long=s.pierce?22:sniper?26:10;c.globalAlpha=.32;line(c,[[-long,0],[-3,0]],s.critical?P.sun:P.light,sniper?2:3);c.globalAlpha=1;oval(c,0,0,sniper?7:5,sniper?2.5:4,s.critical?P.sun:P.green);oval(c,-1,-1.4,2.2,1.2,P.cream,false);leaf(c,-4,0,3,-1.3,P.dark);if(s.pierce)shapeTip(c);if(s.critical)star(c,1,-6,3.5,P.critical,time*4);c.restore()}
function drawHeroShot(c,s,time,travel){if(s.heroId==='vanguard'){c.globalAlpha=.25;line(c,[[-17,0],[-5,0]],'#9cff7d',5);c.globalAlpha=1;oval(c,0,0,6,5,'#55b95e');oval(c,1,-2,2.4,1.5,'#ddffad',false);leaf(c,-4,2,3,-1.9,'#2c7947')}else if(s.heroId==='warden'){c.globalAlpha=.22;line(c,[[-15,0],[-3,0]],'#ffe47b',7);c.globalAlpha=1;star(c,0,0,6,'#ffd35e',time*5);oval(c,0,0,3.2,3.2,'#fff6bf',false);for(const q of [-1,1])leaf(c,-3,q*2,2.5,q*1.2,'#ffe582')}else if(s.heroId==='sentinel'){const long=s.heroPierce?38:22;c.globalAlpha=s.heroPierce?.42:.22;line(c,[[-long,0],[-2,0]],s.heroPierce?'#d8fff4':'#78d4b6',s.heroPierce?4:2);c.globalAlpha=1;line(c,[[-7,0],[8,0]],'#39796e',s.heroPierce?3:2);line(c,[[8,0],[3,-2],[3,2],[8,0]],'#e5fff0',1.5);if(s.heroPierce){c.globalAlpha=.65;line(c,[[-25,-3],[4,-3]],'#92f5d8',1)}}else if(s.heroId==='controller'){c.globalAlpha=.2;line(c,[[-18,4],[-10,-2],[-3,0]],'#75f0ce',5);c.globalAlpha=1;c.save();c.rotate(time*3+travel);oval(c,0,0,5,3,'#63c6aa');oval(c,1,-1,2,1.3,'#dffff1',false);for(let i=0;i<3;i++)leaf(c,-3+i*3,3,2.5,-1+i*.8,'#cba4df');c.restore()}else{line(c,[[-12,0],[0,0]],s.color,3);oval(c,0,0,5,4,s.color)}}
function shapeTip(c){line(c,[[4,-2],[8,0],[4,2]],P.light,1.5)}
